import json

def recover_relations(response: str, atoms: dict[str, str]):
    relations = []

    # Cause-Effect
    if "because" in response or "caused" in response or "led to" in response or "resulted in" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} because" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Cause-Effect",
                        "coupling": "entailment",
                        "strength_band": "strong"
                    })

    # Evidence
    if "shows" in response or "indicates" in response or "confirms" in response or "as shown by" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} shows" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Evidence",
                        "coupling": "entailment",
                        "strength_band": "strong"
                    })

    # Restatement
    if "that is" in response or "in other words" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} that is" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Restatement",
                        "coupling": "equivalence",
