        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} although" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Concession",
                        "coupling": "none",
                        "strength_band": "weak"
                    })

    # Alternative
    if "either" in response or "or" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} either" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Alternative",
                        "coupling": "exclusive",
                        "strength_band": "strong"
                    })

    # Disjunction
    if "at least one" in response or "perhaps both" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} at least one" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Disjunction",
                        "coupling": "co_necessity",
                        "strength_band": "moderate"
                    })

    # Precedence
    if "before" in response or "prior to" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} before" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Precedence",
                        "coupling": "none",
